import{_ as o,l as d,o as a,c as l,v as t,p as n,x as i,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"嵌入与重排模型服务","description":"","frontmatter":{"title":"嵌入与重排模型服务","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/embedding-serving.md","filePath":"llm/embedding-serving.md","lastUpdated":1789023840000}'),h={name:"llm/embedding-serving.md"};function m(E,e,A,_,L,u){const r=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="嵌入与重排模型服务" tabindex="-1">嵌入与重排模型服务 <a class="header-anchor" href="#嵌入与重排模型服务" aria-label="Permalink to &quot;嵌入与重排模型服务&quot;">​</a></h1><div class="epigraph"><p>双编码器一次前向吐向量，没有逐步 decode，也没有 KV 墙；批处理回到普通 BERT 式 GEMM，调度却仍常被误套成自回归引擎。</p><footer>—— Reimers &amp; Gurevych, Sentence-BERT, EMNLP 2019；重排器是交叉编码器，计算随候选对数涨</footer></div><p><a href="/llm/vision-encoder-pipeline">上一课</a>仍接到自回归 LLM。检索栈里还有嵌入模型与重排模型：Sentence-BERT 把句子映到向量，用余弦召回；交叉编码器把 (查询, 文档) 一起编码打分。本课写服务画像差异：无 KV 缓存、无 TPOT、吞吐随 batch 与序列长度走普通屋顶线。用 vLLM 的连续批去套嵌入，会买一套用不上的分页 KV。Hugging Face TEI 一类专用服务才对症。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌入请求是一次 prefill 式前向，输出 \\(d\\) 维向量，可大批、可padding。重排是对每个候选一次交叉编码，\\(k\\) 候选就是 \\(k\\) 次（或拼 batch）。缺口是不要用 decode 会计：这里没有 \\(\\mathrm{KV}(n)\\) 随生成增长，有的是短序列的高 QPS。延迟 SLA 是 p99 毫秒级向量，不是 TPOT。把嵌入与 LLM 放同一连续批，形状与掩码都不同，核融合也不同。</p><p>动态 padding：批内按最长序列 pad，过长尾巴浪费。应按长度分桶，与训练不同，这是服务分桶。</p><p><span class="marginnote">重排器的 FLOPs 随候选数线性，召回 \\(k=200\\) 再重排 50 是典型。成本模型应写在检索路径上，不要记进「每个用户问题一个 LLM token」。RAG 的隐藏账单往往在这里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>嵌入：静态或半静态形状，CUDA Graph 友好，<code>torch.compile</code> 收益比 LLM decode 更干净。大 batch 直到拐点。多卡用数据并行复制模型，不必 TP——模型往往放得进单卡。重排：候选 batch 维，注意注意力掩码。与 LLM 协同：异步队列，不要在 LLM 的 GPU 上同步插一条嵌入前向（打乱 decode 池工作点）。</p><p>向量维与归一化是契约（是否 L2），服务端必须与训练一致，否则检索静默变差。</p>',10)),(a(),n(c,null,{default:i(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20EMB%5B%22%E5%8F%8C%E7%BC%96%E7%A0%81%E5%99%A8%20batch%22%5D%0A%20%20DOC%5B%22%E6%96%87%E6%A1%A3%E5%BA%93%22%5D%20--%3E%20ANN%5B%22ANN%20%E5%8F%AC%E5%9B%9E%22%5D%0A%20%20EMB%20--%3E%20ANN%0A%20%20ANN%20--%3E%20RER%5B%22%E4%BA%A4%E5%8F%89%E7%BC%96%E7%A0%81%E5%99%A8%E9%87%8D%E6%8E%92%22%5D%0A%20%20RER%20--%3E%20LLM%5B%22%E5%8F%AF%E9%80%89%3A%20%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>算术强度随 \\(B\\) 与 \\(n\\) 升，容易 compute-bound，MFU 可比 LLM decode 高一个数量级。这解释了为什么同一张卡跑嵌入「看起来利用率很好」、跑聊天 decode「利用率很差」——不是嵌入实现更强，是工作点不同。成本 \\(C\\) 按请求或按 token 计都可以，但不要用 LLM 的 \\(C_{\\mathrm{tok}}\\) 乘嵌入 token。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要为嵌入建 KV 池。不要把交叉编码器当双编码器用（QPS 会垮）。下一课回到 LLM：权重如何加载与流式进 GPU，这才是自回归服务启动的账单。</p><p>出处：Reimers &amp; Gurevych, EMNLP 2019。TEI 等为工程实现。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>嵌入无 decode KV；服务画像是短序列高 QPS GEMM。</li><li>重排成本随候选数线性，是 RAG 隐藏账单。</li><li>长度分桶；CUDA Graph / compile 比 LLM decode 更适用。</li><li>与 LLM 分池，避免打乱 \\(B^\\star\\)。</li><li>归一化与维是检索契约。</li><li>下一课：权重加载与流式。</li><li>出处：Reimers &amp; Gurevych, 2019。</li></ul>',7))])}const b=o(h,[["render",m]]);export{M as __pageData,b as default};
